// Transport-specific typesupport TU fragment for a ros2 rpc_client.
// Auto-generated by ibmw_gen. The thread-form RpcLoop helper
// and IBMW_TS_RPC_CLIENT_LOOP_* macro pair live in the companion inc.h so the
// ROS2 path stays distinct from the DDS coroutine form.

namespace ros2_rpc_demo {

template <typename SelfT>
inline void _ibmw_ros2_rpc_client_loop_body_impl(SelfT* self) {
  MW_INFO("Start RpcLoop.");

  uint32_t count = 0;
  while (self->run_flag_) {
    std::this_thread::sleep_for(
        std::chrono::milliseconds(static_cast<uint32_t>(1000 / self->rpc_frq_)));
    count++;

    MW_INFO("Loop count : {} -------------------------", count);

    example_ros2::srv::RosTestRpc_Request req;
    example_ros2::srv::RosTestRpc_Response rsp;

    // IBMW_RPC_CLIENT_REQUEST_PARAMETER_BUILD_ROS_TEST_RPC_BEGIN
    req.data.assign(count % 8 + 1, static_cast<uint8_t>(count));
    // IBMW_RPC_CLIENT_REQUEST_PARAMETER_BUILD_ROS_TEST_RPC_END

    auto ctx_ptr = self->access_->NewContextSharedPtr();
    ctx_ptr->SetTimeout(std::chrono::seconds(3));

    MW_INFO("start new service call. req:\n{}", example_ros2::srv::to_yaml(req));

    auto status = self->access_->RosTestRpc(ctx_ptr, req, rsp);

    if (status.OK()) {
      // IBMW_RPC_CLIENT_RESPONSE_PARAMETER_CONSUME_ROS_TEST_RPC_BEGIN
      MW_INFO("Client get rpc ret, status: {}, rsp: {}",
              status.ToString(), example_ros2::srv::to_yaml(rsp));
      // IBMW_RPC_CLIENT_RESPONSE_PARAMETER_CONSUME_ROS_TEST_RPC_END
    } else {
      // IBMW_RPC_CLIENT_RETURN_STATUS_HANDLING_ROS_TEST_RPC_BEGIN
      MW_ERROR("Client get rpc error ret, status: {}",
               status.ToString());
      // IBMW_RPC_CLIENT_RETURN_STATUS_HANDLING_ROS_TEST_RPC_END
    }
  }

  MW_INFO("Exit RpcLoop.");
}

}  // namespace ros2_rpc_demo
